param([Parameter(Mandatory=$true)][string]$Archive)
$ErrorActionPreference='Stop';$name=[IO.Path]::GetFileNameWithoutExtension($Archive);$sum="$Archive.sha256";$line=@(Get-Content $sum|Where-Object{$_.Trim()});if($line.Count-ne 1-or $line[0]-notmatch '^([0-9A-Fa-f]{64})\s+\*?(.+)$'-or (Get-FileHash $Archive -Algorithm SHA256).Hash-ne $Matches[1]){throw 'Checksum validation failed.'};$tmp=Join-Path $env:RUNNER_TEMP "validate-$PID";try{Expand-Archive $Archive $tmp;$root=Join-Path $tmp $name;& (Join-Path $root 'bin\autolith.ps1') --autolith-release-probe;if($LASTEXITCODE){throw 'Release probe failed.'}}finally{if(Test-Path $tmp){Remove-Item -Recurse -Force $tmp}}
